import React, { useState } from "react";
import { getAuth, createUserWithEmailAndPassword, signInWithEmailAndPassword } from "firebase/auth";
import NavBar from "../Components/NavBar"; 
import Footer from "../Components/Footer";
import './account.css';

const auth = getAuth(); // Use your initialized Firebase app's auth instance

export default function Account() {
  const [signUpData, setSignUpData] = useState({
    username: "",
    email: "",
    password: "",
    confirmPassword: ""
  });
  const [signInData, setSignInData] = useState({ username: "", password: "" });

  const handleSignUpChange = (e) => {
    setSignUpData({ ...signUpData, [e.target.name]: e.target.value });
  };

  const handleSignInChange = (e) => {
    setSignInData({ ...signInData, [e.target.name]: e.target.value });
  };

  const handleSignUp = async (e) => {
    e.preventDefault();
    if (signUpData.password !== signUpData.confirmPassword) {
      alert("Passwords do not match!");
      return;
    }
    try {
      await createUserWithEmailAndPassword(auth, signUpData.email, signUpData.password);
      alert("User registered successfully!");
      // Optionally reset form or redirect here
    } catch (error) {
      alert(error.message);
    }
  };

  const handleSignIn = async (e) => {
    e.preventDefault();
    try {
      await signInWithEmailAndPassword(auth, signInData.username, signInData.password);
      alert("Signed in successfully!");
      // Handle post-sign in actions (redirect, set user context)
    } catch (error) {
      alert(error.message);
    }
  };

  return (
    <>
      <NavBar />
      <div className="acc-page">
        <section className="account">
          <input type="checkbox" id="check" aria-hidden="true" />

          <div className="signUp">
            <form onSubmit={handleSignUp}>
              <label htmlFor="check" aria-hidden="true" className="signup">
                SignUp
              </label>
              <input
                type="text"
                name="username"
                placeholder="User Name"
                value={signUpData.username}
                onChange={handleSignUpChange}
                required
              />
              <input
                type="email"
                name="email"
                placeholder="Email"
                value={signUpData.email}
                onChange={handleSignUpChange}
                required
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                value={signUpData.password}
                onChange={handleSignUpChange}
                required
              />
              <input
                type="password"
                name="confirmPassword"
                placeholder="Confirm Password"
                value={signUpData.confirmPassword}
                onChange={handleSignUpChange}
                required
              />
              <button type="submit">Sign Up</button>
            </form>
          </div>

          <div className="signIn">
            <form onSubmit={handleSignIn}>
              <label htmlFor="check" aria-hidden="true">
                SignIn
              </label>
              <input
                type="email"
                name="username"
                placeholder="Email"
                id="username"
                value={signInData.username}
                onChange={handleSignInChange}
                required
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                id="password"
                value={signInData.password}
                onChange={handleSignInChange}
                required
              />
              <button type="submit">Sign In</button>
              <p>
                <a href="#">Forget account?</a>
              </p>
            </form>
          </div>
        </section>
      </div>
      <Footer />
    </>
  );
}
